<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Ubuntu Desktop Clone</title>
    <style>
        :root {
            --ubuntu-purple: #300a24;
            --ubuntu-orange: #E95420;
            --dark-bg: #2c001e;
            --win-bg: #3d3d3d;
            --win-border: #1a1a1a;
            --text-color: #ffffff;
            --accent: #5e5e5e;
        }

        body, html {
            margin: 0;
            padding: 0;
            width: 100%;
            height: 100%;
            font-family: 'Segoe UI', Ubuntu, Cantarell, sans-serif;
            overflow: hidden;
            background-color: var(--ubuntu-purple);
        }

        #desktop {
            position: relative;
            width: 100vw;
            height: 100vh;
            background: linear-gradient(135deg, #4a1b3d 0%, #2c001e 100%);
            background-size: cover;
        }

        /* Taskbar / Dock */
        #taskbar {
            position: absolute;
            bottom: 10px;
            left: 50%;
            transform: translateX(-50%);
            height: 60px;
            background: rgba(0, 0, 0, 0.6);
            backdrop-filter: blur(10px);
            border-radius: 12px;
            display: flex;
            align-items: center;
            padding: 0 15px;
            gap: 15px;
            z-index: 1000;
            border: 1px solid rgba(255,255,255,0.1);
        }

        .launcher {
            width: 45px;
            height: 45px;
            border-radius: 8px;
            border: none;
            cursor: pointer;
            color: white;
            font-size: 20px;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: background 0.2s, transform 0.1s;
            background: var(--accent);
        }

        .launcher:hover {
            background: var(--ubuntu-orange);
            transform: translateY(-5px);
        }

        /* Window System */
        .window {
            position: absolute;
            min-width: 360px;
            min-height: 240px;
            width: 500px;
            height: 400px;
            background: var(--win-bg);
            border-radius: 8px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
            display: none;
            flex-direction: column;
            color: var(--text-color);
            overflow: hidden;
            border: 1px solid var(--win-border);
            z-index: 10;
        }

        .win-header {
            height: 35px;
            background: #2a2a2a;
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 10px;
            cursor: move;
            user-select: none;
        }

        .win-title {
            font-size: 13px;
            font-weight: bold;
            opacity: 0.9;
        }

        .win-close {
            width: 24px;
            height: 24px;
            background: #cc4444;
            border: none;
            color: white;
            border-radius: 50%;
            cursor: pointer;
            font-weight: bold;
            line-height: 1;
        }

        .win-close:hover {
            background: #ff0000;
        }

        .win-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            overflow: hidden;
            position: relative;
        }

        /* Files App */
        #files-toolbar {
            background: #333;
            padding: 5px 10px;
            display: flex;
            gap: 10px;
            align-items: center;
            border-bottom: 1px solid #222;
        }

        #files-path {
            font-family: monospace;
            font-size: 13px;
            background: #1e1e1e;
            padding: 2px 8px;
            border-radius: 4px;
            flex: 1;
        }

        #files-up {
            cursor: pointer;
            background: var(--accent);
            border: none;
            color: white;
            padding: 2px 10px;
            border-radius: 4px;
            font-size: 12px;
        }

        #files-list {
            flex: 1;
            overflow-y: auto;
            padding: 10px;
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(80px, 1fr));
            gap: 15px;
            align-content: start;
        }

        .fs-item {
            display: flex;
            flex-direction: column;
            align-items: center;
            text-align: center;
            cursor: pointer;
            padding: 10px 5px;
            border-radius: 4px;
            font-size: 12px;
            transition: background 0.2s;
            user-select: none;
        }

        .fs-item:hover {
            background: rgba(255,255,255,0.1);
        }

        .fs-item::before {
            content: '📁';
            font-size: 30px;
            margin-bottom: 5px;
        }

        .fs-item.file::before {
            content: '📄';
        }

        /* Notepad App */
        #notepad-tabs-container {
            display: flex;
            background: #2a2a2a;
            border-bottom: 1px solid #111;
            overflow-x: auto;
        }

        #tabs {
            display: flex;
            flex: 1;
        }

        .tab {
            padding: 8px 15px;
            background: #3d3d3d;
            border-right: 1px solid #2a2a2a;
            cursor: pointer;
            font-size: 12px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .tab.active {
            background: var(--win-bg);
            border-bottom: 2px solid var(--ubuntu-orange);
        }

        #new-tab {
            padding: 0 15px;
            background: #2a2a2a;
            color: white;
            border: none;
            cursor: pointer;
            font-weight: bold;
        }

        #editor {
            width: 100%;
            height: 100%;
            background: var(--win-bg);
            color: white;
            border: none;
            resize: none;
            padding: 15px;
            box-sizing: border-box;
            font-family: 'Courier New', monospace;
            outline: none;
        }
    </style>
</head>
<body>

<div id="desktop">
    <!-- Taskbar -->
    <div id="taskbar">
        <button id="open-files" class="launcher" title="Files">📁</button>
        <button id="open-notepad" class="launcher" title="Notepad">📝</button>
    </div>

    <!-- Files Window -->
    <div id="files-window" class="window" style="top: 50px; left: 100px;">
        <div class="win-header">
            <span class="win-title">Files</span>
            <button class="win-close">&times;</button>
        </div>
        <div class="win-content">
            <div id="files-toolbar">
                <button id="files-up">UP</button>
                <span id="files-path">/</span>
            </div>
            <div id="files-list"></div>
        </div>
    </div>

    <!-- Notepad Window -->
    <div id="notepad-window" class="window" style="top: 80px; left: 150px;">
        <div class="win-header">
            <span class="win-title">Notepad</span>
            <button class="win-close">&times;</button>
        </div>
        <div class="win-content">
            <div id="notepad-tabs-container">
                <div id="tabs"></div>
                <button id="new-tab">+</button>
            </div>
            <textarea id="editor"></textarea>
        </div>
    </div>
</div>

<script>
    /** 
     * FILE SYSTEM DATA
     */
    const fsData = {
        '/': { type: 'dir', children: ['bin', 'etc', 'home', 'usr', 'var'] },
        '/bin': { type: 'dir', children: ['bash', 'ls', 'grep'] },
        '/etc': { type: 'dir', children: ['hosts', 'passwd', 'network'] },
        '/home': { type: 'dir', children: ['user'] },
        '/home/user': { type: 'dir', children: ['Documents', 'Downloads', 'Pictures'] },
        '/home/user/Documents': { type: 'dir', children: ['todo.txt', 'notes.txt'] },
        '/home/user/Downloads': { type: 'dir', children: [] },
        '/home/user/Pictures': { type: 'dir', children: ['wallpaper.jpg', 'profile.png'] },
        '/usr': { type: 'dir', children: ['bin', 'lib', 'share'] },
        '/var': { type: 'dir', children: ['log', 'tmp'] },
        // Files (simplified)
        '/bin/bash': { type: 'file' }, '/bin/ls': { type: 'file' }, '/bin/grep': { type: 'file' },
        '/etc/hosts': { type: 'file' }, '/etc/passwd': { type: 'file' }, '/etc/network': { type: 'file' },
        '/home/user/Documents/todo.txt': { type: 'file' }, '/home/user/Documents/notes.txt': { type: 'file' },
        '/home/user/Pictures/wallpaper.jpg': { type: 'file' }, '/home/user/Pictures/profile.png': { type: 'file' },
        '/usr/bin': { type: 'dir', children: [] }, '/usr/lib': { type: 'dir', children: [] }, '/usr/share': { type: 'dir', children: [] },
        '/var/log': { type: 'dir', children: ['syslog'] }, '/var/tmp': { type: 'dir', children: [] },
        '/var/log/syslog': { type: 'file' }
    };

    let currentPath = '/';

    function renderFiles() {
        const listElem = document.getElementById('files-list');
        const pathElem = document.getElementById('files-path');
        pathElem.textContent = currentPath;
        listElem.innerHTML = '';

        const folder = fsData[currentPath];
        if (!folder || !folder.children) return;

        folder.children.forEach(name => {
            const fullPath = (currentPath === '/' ? '' : currentPath) + '/' + name;
            const item = document.createElement('div');
            item.className = 'fs-item';
            const node = fsData[fullPath];
            if (node && node.type === 'file') item.classList.add('file');
            item.textContent = name;

            item.ondblclick = () => {
                if (node && node.type === 'dir') {
                    currentPath = fullPath;
                    renderFiles();
                }
            };
            listElem.appendChild(item);
        });
    }

    document.getElementById('files-up').onclick = () => {
        if (currentPath === '/') return;
        const parts = currentPath.split('/').filter(Boolean);
        parts.pop();
        currentPath = '/' + parts.join('/');
        if (currentPath === '') currentPath = '/';
        renderFiles();
    };

    /** 
     * NOTEPAD PERSISTENCE & TABS
     */
    let notepadTabs = JSON.parse(localStorage.getItem('ubuntu_notepad_tabs')) || [
        { id: Date.now(), name: 'Untitled', content: '' }
    ];
    let activeTabId = localStorage.getItem('ubuntu_notepad_active_id') || notepadTabs[0].id;

    function saveNotepad() {
        localStorage.setItem('ubuntu_notepad_tabs', JSON.stringify(notepadTabs));
        localStorage.setItem('ubuntu_notepad_active_id', activeTabId);
    }

    function renderNotepadTabs() {
        const tabContainer = document.getElementById('tabs');
        tabContainer.innerHTML = '';
        notepadTabs.forEach(tab => {
            const div = document.createElement('div');
            div.className = 'tab' + (tab.id == activeTabId ? ' active' : '');
            div.textContent = tab.name;
            div.onclick = () => {
                activeTabId = tab.id;
                updateEditorContent();
                renderNotepadTabs();
                saveNotepad();
            };
            tabContainer.appendChild(div);
        });
    }

    function updateEditorContent() {
        const editor = document.getElementById('editor');
        const tab = notepadTabs.find(t => t.id == activeTabId);
        editor.value = tab ? tab.content : '';
    }

    document.getElementById('new-tab').onclick = () => {
        const newId = Date.now();
        notepadTabs.push({ id: newId, name: 'Untitled ' + (notepadTabs.length + 1), content: '' });
        activeTabId = newId;
        renderNotepadTabs();
        updateEditorContent();
        saveNotepad();
    };

    document.getElementById('editor').oninput = (e) => {
        const tab = notepadTabs.find(t => t.id == activeTabId);
        if (tab) tab.content = e.target.value;
        saveNotepad();
    };

    /** 
     * WINDOW MANAGEMENT
     */
    function initWindow(winId, openBtnId) {
        const win = document.getElementById(winId);
        const btn = document.getElementById(openBtnId);

        btn.onclick = () => {
            win.style.display = 'flex';
            // Bring to front
            document.querySelectorAll('.window').forEach(w => w.style.zIndex = 10);
            win.style.zIndex = 100;
        };

        win.querySelector('.win-close').onclick = () => {
            win.style.display = 'none';
        };

        // Simple Dragging logic
        const header = win.querySelector('.win-header');
        let isDragging = false, offsetX, offsetY;

        header.onmousedown = (e) => {
            isDragging = true;
            offsetX = e.clientX - win.offsetLeft;
            offsetY = e.clientY - win.offsetTop;
            document.querySelectorAll('.window').forEach(w => w.style.zIndex = 10);
            win.style.zIndex = 100;
        };

        window.onmousemove = (e) => {
            if (!isDragging) return;
            win.style.left = (e.clientX - offsetX) + 'px';
            win.style.top = (e.clientY - offsetY) + 'px';
        };

        window.onmouseup = () => {
            isDragging = false;
        };
    }

    // Init everything
    initWindow('files-window', 'open-files');
    initWindow('notepad-window', 'open-notepad');
    renderFiles();
    renderNotepadTabs();
    updateEditorContent();

</script>
</body>
</html>
